/* prog18_caesar_cipher – reconstructed from the obfuscated binary
 *
 * Usage: prog18_caesar_cipher <shift> <text>
 *
 * The program applies a Caesar cipher to <text> using the integer
 * shift value <shift>.  The shift is normalised to the range 0‑25
 * (negative values are wrapped correctly).  Upper‑case and lower‑case
 * letters are rotated preserving case; all other characters are left
 * unchanged.  The transformed text is written to stdout followed by a
 * newline.  If the number of arguments is not exactly three, or if the
 * input text is longer than 1024 characters, the program prints
 * "USAGE" (followed by a newline) and exits.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    /* The original binary expects exactly three arguments:
       program name, shift, and text. */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *text = argv[2];
    size_t len = strlen(text);

    /* The original program refuses strings longer than 1024 bytes. */
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }

    /* Convert the shift argument to a long integer.  The original code
       normalises the value modulo 26 using a magic‑number multiplication;
       the effect is the same as the portable computation below. */
    long raw_shift = strtol(argv[1], NULL, 10);
    int shift = (int)((raw_shift % 26 + 26) % 26);   /* 0 … 25 */

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (isupper(c)) {
            c = (unsigned char)('A' + (c - 'A' + shift) % 26);
        } else if (islower(c)) {
            c = (unsigned char)('a' + (c - 'a' + shift) % 26);
        }
        putc(c, stdout);
    }
    putc('\n', stdout);
    return 0;
}
